class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        longest_substring = 0
        substring = ""

        for char in s:
            if char not in substring:
                substring += char
            else:
                longest_substring = max(longest_substring, len(substring))
                substring = substring[substring.index(char)+1:] + char

